\label{lem:gamma-contraction}
For every small $\delta>0$, there are $A(\delta)$ and
$C_\delta$ with $A(\delta) \to 0$ as $\delta \to 0$ such that
\begin{align}
d_{1,\delta}\bigl(\Gamma_\tau(\eta),\Gamma_\tau(\eta')\bigr)
& \leq
\left(
A(\delta)+\frac{C_\delta}{\tau}
\right)
d_{1,\delta}(\eta,\eta').
\label{eq:gamma-contraction}
\end{align}
